/**
 * OUR MEASURED RESULTS — loaded at runtime from /public/results/tcad-results.json.
 *
 * Contract: research-data/published/tcad-results.schema.json (schemaVersion "1.0"),
 * extended with "A5-LR", per-metric 95% CIs ("ci95"), "level" and "denominator".
 * The file is generated by scripts/import_research_data.py from research-data/measured/.
 * Status "awaiting_measurements" with no experiments renders the protocol view.
 */

export type EndpointMetric =
  | "rocAuc"
  | "prAuc"
  | "reportTpr"
  | "reportFpr"
  | "precision"
  | "f1"
  | "frameTpr"
  | "frameFpr"
  | "eventDetectionRate"
  | "meanDetectionDelayS"
  | "latencyP95Ms";

export interface EndpointExperiment {
  configuration: string;
  condition: string;
  dataset: string;
  runId: string;
  sourceFile: string;
  hardware: string;
  nScenarios: number;
  level?: string;
  denominator?: { rows: number; positives: number; negatives: number };
  metrics: Partial<Record<EndpointMetric, number>>;
  ci95?: Partial<Record<EndpointMetric, [number, number]>>;
}

export interface ResultsEndpoint {
  schemaVersion: "1.0";
  status: "awaiting_measurements" | "measured";
  provenance: string;
  experiments: EndpointExperiment[];
}

export const emptyEndpoint: ResultsEndpoint = {
  schemaVersion: "1.0",
  status: "awaiting_measurements",
  provenance: "No project-run results have been supplied or verified",
  experiments: [],
};

export const endpointMetricSpecs: { key: EndpointMetric; label: string; unit: "" | "%" | "s" | "ms"; higherIsBetter: boolean; definition: string }[] = [
  { key: "rocAuc", label: "AUROC", unit: "", higherIsBetter: true, definition: "Threshold-free ranking quality of the anomaly score over all scored report assessments." },
  { key: "prAuc", label: "AUPRC", unit: "", higherIsBetter: true, definition: "Area under precision–recall; informative because only 4.4% of reports are positives." },
  { key: "reportTpr", label: "TPR (report)", unit: "%", higherIsBetter: true, definition: "Contradictory reports flagged ÷ all contradictory reports, at the threshold frozen on validation (target FPR 5%)." },
  { key: "reportFpr", label: "FPR (report)", unit: "%", higherIsBetter: false, definition: "Benign reports flagged ÷ all benign reports at the same frozen threshold." },
  { key: "precision", label: "Precision", unit: "%", higherIsBetter: true, definition: "Flagged reports that were truly contradictory." },
  { key: "f1", label: "F1", unit: "", higherIsBetter: true, definition: "Harmonic mean of precision and TPR." },
  { key: "frameTpr", label: "TPR (frame)", unit: "%", higherIsBetter: true, definition: "Frames containing a contradictory report that raised any alert." },
  { key: "frameFpr", label: "FPR (frame)", unit: "%", higherIsBetter: false, definition: "Clean frames that raised any alert." },
];

/** Accepts the v1.0 contract; anything malformed degrades to the awaiting state. */
export function validateEndpoint(raw: unknown): ResultsEndpoint {
  if (!raw || typeof raw !== "object") return emptyEndpoint;
  const r = raw as Partial<ResultsEndpoint>;
  if (r.schemaVersion !== "1.0" || !Array.isArray(r.experiments)) return emptyEndpoint;
  const experiments = r.experiments.filter(
    (e): e is EndpointExperiment =>
      !!e &&
      typeof e.configuration === "string" &&
      typeof e.runId === "string" &&
      typeof e.sourceFile === "string" &&
      typeof e.nScenarios === "number" &&
      e.nScenarios >= 1 &&
      !!e.metrics &&
      typeof e.metrics === "object",
  );
  return {
    schemaVersion: "1.0",
    status: experiments.length && r.status === "measured" ? "measured" : "awaiting_measurements",
    provenance: typeof r.provenance === "string" ? r.provenance : "",
    experiments,
  };
}
